+// TestHead_RaceBetweenHistogramSeriesCreationAndGC verifies that AppendHistogram
+// correctly sets pendingCommit=true when a histogram sample is accepted, preventing
+// the GC from collecting a series that has a pending commit.
+func TestHead_RaceBetweenHistogramSeriesCreationAndGC(t *testing.T) {
+	for _, tc := range []struct {
+		name    string
+		h       *histogram.Histogram
+		fh      *histogram.FloatHistogram
+	}{
+		{
+			name: "integer histogram",
+			h:    tsdbutil.GenerateTestHistogram(1),
+		},
+		{
+			name: "float histogram",
+			fh:   tsdbutil.GenerateTestFloatHistogram(1),
+		},
+	} {
+		t.Run(tc.name, func(t *testing.T) {
+			head, _ := newTestHead(t, 1000, compression.None, false)
+			require.NoError(t, head.Init(0))
+
+			const totalSeries = 100_000
+			series := make([]labels.Labels, totalSeries)
+			for i := range totalSeries {
+				series[i] = labels.FromStrings("foo", strconv.Itoa(i))
+			}
+			done := atomic.NewBool(false)
+
+			go func() {
+				defer done.Store(true)
+				app := head.Appender(context.Background())
+				defer func() {
+					if err := app.Commit(); err != nil {
+						t.Errorf("Failed to commit: %v", err)
+					}
+				}()
+				for i := range totalSeries {
+					_, err := app.AppendHistogram(0, series[i], 100, tc.h, tc.fh)
+					if err != nil {
+						t.Errorf("Failed to append histogram: %v", err)
+						return
+					}
+				}
+			}()
+
+			// Don't check the atomic.Bool on all iterations in order to perform more gc
+			// iterations and make the race condition more likely.
+			for i := 1; i%128 != 0 || !done.Load(); i++ {
+				head.gc()
+			}
+
+			require.Equal(t, totalSeries, int(head.NumSeries()))
+		})
+	}
+}
